css:
:scope { width: min(100%, 1338px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 14; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i2 { grid-column: 1 / span 14; grid-row: 5 / span 25; font-family: var(--os-font-heading); font-size: 65.6px; font-weight: 700; line-height: 1; letter-spacing: -0.025em; color: var(--os-color-text); }
.gx__i3 { grid-column: 1 / span 13; grid-row: 34 / span 13; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__p4 { grid-column: 15 / span 9; grid-row: 37 / span 50;  border: 2px solid var(--os-color-border); border-radius: 0px; }
.gx__i5 { grid-column: 16 / span 8; grid-row: 40 / span 2; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 400; line-height: 1.4; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i6 { grid-column: 17 / span 7; grid-row: 45 / span 10; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i7 { grid-column: 1 / span 13; grid-row: 49 / span 30; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i8 { grid-column: 17 / span 7; grid-row: 59 / span 10; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i9 { grid-column: 17 / span 7; grid-row: 74 / span 10; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i10 { grid-column: 1 / span 2; grid-row: 84 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-surface); }
.gx__i11 { grid-column: 3 / span 4; grid-row: 84 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i12 { grid-column: 15 / span 9; grid-row: 89 / span 2; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 400; line-height: 1.4; letter-spacing: 0.16em; text-transform: uppercase; text-align: right; color: inherit; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 52px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__p4 { display: none; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i8 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i9 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i10 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
}
